SELECT ?zone ?sensor ?ts (str(?node) AS ?node) WHERE {
  ?node a brick:Zone .
  FILTER (regex(str(?node), "Perimeter_(top|mid)_ZN_3"))
}

SELECT DISTINCT ?node WHERE {
  ?node a brick:Zone .
  FILTER (regex(str(?node), "ZN_3"))
}

SELECT ?sensor ?ts WHERE {
  ?sensor a brick:AirTemperatureSensor ;
          brick:hasPrimaryLocation ?zone .
  ?zone rdfs:label ?zl .
  FILTER (regex(?zl, "Perimeter_(top|mid)_ZN_3$"))
  ?link ref:hasPoint ?sensor .
  ?link ref:hasTimeseriesId ?ts .
}

SELECT ?sensor WHERE {
  ?sensor a brick:AirTemperatureSensor ;
          brick:hasPrimaryLocation ?zone .
  ?zone rdfs:label ?zl .
  FILTER (regex(?zl, "Perimeter_(top|mid)_ZN_3$"))
}

PREFIX b: <http://buildgraph.org/BG_large_office_2004_0000#>
SELECT ?sensor ?ts ?zl WHERE {
  ?sensor a brick:AirTemperatureSensor .
  ?sensor brick:hasPrimaryLocation ?zone .
  ?zone rdfs:label ?zl .
  FILTER (regex(?zl, "Perimeter_(top|mid)_ZN_3$"))
  OPTIONAL { ?link ref:hasPoint ?sensor . ?link ref:hasTimeseriesId ?ts . }
}

SELECT ?sensor ?zl ?ts WHERE {
  ?sensor a brick:AirTemperatureSensor .
  ?sensor brick:hasLocation ?zone .
  ?zone rdfs:label ?zl .
  FILTER (regex(?zl, "Perimeter_(top|mid)_ZN_3$"))
  OPTIONAL { ?link ref:hasPoint ?sensor ; ref:hasTimeseriesId ?ts . }
  OPTIONAL { ?link2 ref:hasExternalReference ?sensor ; ref:hasTimeseriesId ?ts . }
}

